<?php
/**
 * Content pages: the front page, the pages whose template WordPress picks by
 * slug (page-unternehmen.php, page-kontakt.php, page-faq.php, and the older
 * page-namensschilder.php), plain info pages (page.php) and news articles
 * (single-news.php).
 *
 * - Field groups: acf-json/group_ip_{home,unternehmen,kontakt,faq}.json,
 *   generated by tools/build-acf-json.py (repo root, not deployed).
 * - Styles: assets/css/home.css (front page), content.css (all other pages),
 *   news.css (news); bundles from ip_template_bundle() in inc/assets.php.
 * - Elementor: info pages are still Elementor documents in the database.
 *   ip_page_content() renders them from their stored data without
 *   Elementor (see there).
 */

defined( 'ABSPATH' ) || exit;

/* ── Small render helpers ───────────────────────────────────────────────── */

/**
 * A link target typed by the client: "/kontakt/" becomes a full URL on this
 * site, "#..." stays, anything else (https://, mailto:, tel:) is kept as typed.
 * Returns '' for an empty value. Escape on output (esc_url).
 */
function ip_content_url( $value ) {
	$value = trim( (string) $value );
	if ( '' === $value ) {
		return '';
	}
	if ( str_starts_with( $value, '/' ) && ! str_starts_with( $value, '//' ) ) {
		return home_url( $value );
	}
	return $value;
}

/**
 * Plain text from a textarea as escaped paragraphs: a blank line starts a
 * new paragraph, a single line break becomes <br>. Returns safe HTML.
 */
function ip_paras( $text, $class = '' ) {
	$text = trim( (string) $text );
	if ( '' === $text ) {
		return '';
	}
	$out = '';
	foreach ( preg_split( '/\R\s*\R/', $text ) as $para ) {
		$lines = array_map( 'esc_html', array_map( 'trim', preg_split( '/\R/', trim( $para ) ) ) );
		$out  .= '<p' . ( $class ? ' class="' . esc_attr( $class ) . '"' : '' ) . '>' . implode( '<br>', $lines ) . '</p>';
	}
	return $out;
}

/**
 * Allowed HTML for prose from editors and old Elementor widgets: the post
 * set without inline styles (the old pages carry font-weight and colour
 * spans that would fight the theme). Returns the kses array.
 */
function ip_prose_allowed_html() {
	static $allowed = null;
	if ( null === $allowed ) {
		$allowed = wp_kses_allowed_html( 'post' );
		foreach ( $allowed as $tag => $attrs ) {
			if ( is_array( $attrs ) ) {
				unset( $allowed[ $tag ]['style'] );
			}
		}
	}
	return $allowed;
}

/**
 * HTML from a WYSIWYG field or an old text widget, cleaned for .ip-prose:
 * layout-only <div>/<span> wrappers removed (so the prose spacing rules see
 * the real paragraphs), inline styles dropped, paragraphs added where the
 * text has none. Shortcodes run last, as Elementor's text widget did.
 * Returns safe HTML.
 */
function ip_rich( $html ) {
	$html = (string) $html;
	if ( '' === trim( wp_strip_all_tags( $html, true ) ) && ! preg_match( '/<(img|iframe|table)\b/i', $html ) ) {
		return '';
	}
	$html = preg_replace( '#</?(div|span)\b[^>]*>#i', '', $html );
	$html = wp_kses( $html, ip_prose_allowed_html() );
	$html = wpautop( $html );
	return do_shortcode( $html );
}

/**
 * Section head (DESIGN.md 2): kicker, heading with an optional magenta
 * second half, grey subline. Prints nothing when all parts are empty.
 *
 * @param array $h kicker, title, accent, text (plain, may have line breaks),
 *                 tag (h1/h2, default h2), id (for aria-labelledby), class.
 */
function ip_section_head( $h ) {
	$h = wp_parse_args( $h, array( 'kicker' => '', 'title' => '', 'accent' => '', 'text' => '', 'tag' => 'h2', 'id' => '', 'class' => '' ) );
	if ( '' === $h['kicker'] . $h['title'] . $h['accent'] . $h['text'] ) {
		return;
	}
	$tag = in_array( $h['tag'], array( 'h1', 'h2', 'h3' ), true ) ? $h['tag'] : 'h2';
	echo '<header class="ip-head' . ( $h['class'] ? ' ' . esc_attr( $h['class'] ) : '' ) . '">';
	if ( $h['kicker'] ) {
		echo '<p class="ip-kicker">' . esc_html( $h['kicker'] ) . '</p>';
	}
	if ( $h['title'] || $h['accent'] ) {
		printf(
			'<%1$s class="ip-head__title"%2$s>%3$s%4$s</%1$s>',
			tag_escape( $tag ),
			$h['id'] ? ' id="' . esc_attr( $h['id'] ) . '"' : '',
			esc_html( $h['title'] ),
			$h['accent'] ? ( $h['title'] ? ' ' : '' ) . '<em>' . esc_html( $h['accent'] ) . '</em>' : ''
		);
	}
	if ( $h['text'] ) {
		echo '<div class="ip-sub ip-head__text">' . ip_paras( $h['text'] ) . '</div>'; // phpcs:ignore WordPress.Security.EscapeOutput -- ip_paras() escapes.
	}
	echo '</header>';
}

/**
 * Head data for a section of a page's field group: {$prefix}_kicker,
 * _title, _title_accent (and _text when $with_text).
 */
function ip_section_fields( $prefix, $post_id, $with_text = true ) {
	return array(
		'kicker' => (string) ip_field( $prefix . '_kicker', $post_id ),
		'title'  => (string) ip_field( $prefix . '_title', $post_id ),
		'accent' => (string) ip_field( $prefix . '_title_accent', $post_id ),
		'text'   => $with_text ? (string) ip_field( $prefix . '_text', $post_id ) : '',
	);
}

/** Attachment IDs from an image/gallery value (array of IDs or arrays, single ID). */
function ip_ids( $value ) {
	$ids = array();
	foreach ( (array) $value as $item ) {
		$ids[] = is_array( $item ) ? (int) ( $item['ID'] ?? $item['id'] ?? 0 ) : (int) $item;
	}
	return array_values( array_filter( $ids ) );
}

/**
 * The contact rows every content page shows (Kontakt page, FAQ card,
 * home band), from the site settings. Each row: icon, label, value (plain),
 * url ('' = no link), lines (bool: value has line breaks).
 *
 * @param string[] $which Any of phone, email, fax, address, hours.
 */
function ip_contact_rows( $which = array( 'phone', 'email' ) ) {
	$rows = array();
	foreach ( $which as $key ) {
		switch ( $key ) {
			case 'phone':
				$v = (string) ip_setting( 'phone' );
				if ( $v ) {
					$rows[] = array( 'key' => 'phone', 'icon' => 'phone', 'label' => __( 'Telefon', 'infoplus' ), 'value' => $v, 'url' => ip_tel( $v ) );
				}
				break;
			case 'email':
				$v = (string) ip_setting( 'email' );
				if ( $v && is_email( $v ) ) {
					$rows[] = array( 'key' => 'email', 'icon' => 'mail', 'label' => __( 'E-Mail', 'infoplus' ), 'value' => antispambot( $v ), 'url' => 'mailto:' . antispambot( $v ) );
				}
				break;
			case 'fax':
				$v = (string) ip_setting( 'fax' );
				if ( $v ) {
					$rows[] = array( 'key' => 'fax', 'icon' => 'printer', 'label' => __( 'Telefax', 'infoplus' ), 'value' => $v, 'url' => '' );
				}
				break;
			case 'address':
				$v = trim( ip_one_line( ip_setting( 'company_name' ) ) . "\n" . ip_setting( 'company_address' ) );
				if ( $v ) {
					$rows[] = array( 'key' => 'address', 'icon' => 'pin', 'label' => __( 'Anschrift', 'infoplus' ), 'value' => $v, 'url' => '' );
				}
				break;
			case 'hours':
				$v = ip_hours_rows( ip_setting( 'kontakt_hours' ) );
				if ( $v ) {
					$rows[] = array( 'key' => 'hours', 'icon' => 'clock', 'label' => __( 'Öffnungszeiten', 'infoplus' ), 'value' => $v, 'url' => '' );
				}
				break;
		}
	}
	return $rows;
}

/**
 * Opening hours rows (ip_hours_rows()) as a week: 1 (Monday) to 7 (Sunday)
 * => array( 'from' => 'H:MM', 'to' => 'H:MM' ), closed days absent. Reads
 * day labels like "MO–DO", "Mo-Fr", "FR", "Sa, So" (first two letters of
 * the German day names) and times like "8:00–17:00", "8–17 Uhr" or
 * "08.00 - 16.30". Returns null when a line cannot be read, so callers can
 * fall back to printing the lines as they are. Public holidays are not
 * known here.
 *
 * @return array<int, array{from:string,to:string}>|null
 */
function ip_hours_week( $rows ) {
	$days = array( 'mo' => 1, 'di' => 2, 'mi' => 3, 'do' => 4, 'fr' => 5, 'sa' => 6, 'so' => 7 );
	$week = array();
	foreach ( (array) $rows as $row ) {
		$label = function_exists( 'mb_strtolower' ) ? mb_strtolower( (string) ( $row['label'] ?? '' ) ) : strtolower( (string) ( $row['label'] ?? '' ) );
		if ( ! preg_match( '/(\d{1,2})(?:[:.](\d{2}))?\s*(?:uhr)?\s*(?:-|–|—|bis)\s*(\d{1,2})(?:[:.](\d{2}))?/u', (string) ( $row['value'] ?? '' ), $t ) ) {
			return null;
		}
		$from = sprintf( '%d:%02d', (int) $t[1], (int) ( $t[2] ?? 0 ) );
		$to   = sprintf( '%d:%02d', (int) $t[3], (int) ( $t[4] ?? 0 ) );
		$hit  = array();
		foreach ( preg_split( '/\s*[,\/&+]\s*|\s+und\s+/u', $label ) as $part ) {
			if ( preg_match( '/^\s*([a-zäöü]{2})[a-zäöü.]*\s*(?:(?:-|–|—|bis)\s*([a-zäöü]{2})[a-zäöü.]*)?\s*$/u', $part, $m ) && isset( $days[ $m[1] ] ) ) {
				$a = $days[ $m[1] ];
				$b = ( isset( $m[2] ) && '' !== $m[2] && isset( $days[ $m[2] ] ) ) ? $days[ $m[2] ] : $a;
				for ( $d = $a; $d <= $b; $d++ ) {
					$hit[] = $d;
				}
			} else {
				return null;
			}
		}
		foreach ( $hit as $d ) {
			$week[ $d ] = array( 'from' => $from, 'to' => $to );
		}
	}
	ksort( $week );
	return $week ? $week : null;
}

/** One contact row as an .ip-reach item (tile + label + value). Prints. */
function ip_contact_row( $row ) {
	$tag = $row['url'] ? 'a' : 'div';
	printf(
		'<%1$s class="ip-reach ip-reach--%2$s"%3$s><span class="ip-tile">%4$s</span><span class="ip-reach__body"><span class="ip-reach__label">%5$s</span>',
		tag_escape( $tag ),
		esc_attr( $row['key'] ),
		$row['url'] ? ' href="' . esc_url( $row['url'], array( 'tel', 'mailto' ) ) . '"' : '',
		ip_icon( $row['icon'] ), // phpcs:ignore WordPress.Security.EscapeOutput -- static SVG.
		esc_html( $row['label'] )
	);
	if ( is_array( $row['value'] ) ) { // Opening hours.
		echo '<span class="ip-reach__hours">';
		foreach ( $row['value'] as $line ) {
			printf( '<span><b>%s</b> %s</span>', esc_html( $line['label'] ), esc_html( $line['value'] ) );
		}
		echo '</span>';
	} else {
		echo '<span class="ip-reach__value">' . ip_lines( $row['value'] ) . '</span>'; // phpcs:ignore WordPress.Security.EscapeOutput -- ip_lines() escapes.
	}
	echo '</span></' . tag_escape( $tag ) . '>';
}

/* ── Pages whose template is chosen by slug ─────────────────────────────── */

/**
 * True when this theme renders the page with a template of its own picked by
 * WordPress without a database setting: the front page (front-page.php) or a
 * page-{slug}.php file. Those pages are edited through their fields; their
 * post_content is never printed.
 */
function ip_is_slug_template_page( $post ) {
	$post = get_post( $post );
	if ( ! $post || 'page' !== $post->post_type ) {
		return false;
	}
	if ( 'page' === get_option( 'show_on_front' ) && (int) get_option( 'page_on_front' ) === (int) $post->ID ) {
		return (bool) locate_template( array( 'front-page.php' ) );
	}
	$custom = get_page_template_slug( $post );
	if ( $custom && ! str_starts_with( $custom, 'elementor_' ) ) {
		return false; // A page template chosen in the admin wins over the slug file.
	}
	return '' !== $post->post_name && (bool) locate_template( array( 'page-' . $post->post_name . '.php' ) );
}

/*
 * No block editor for those pages (setup.php does the same for templates/*):
 * their content is fields, and the block editor would offer to write text
 * that never shows. On their edit screen the classic editor box is removed
 * too, and a short note says where the content lives.
 */
add_filter( 'use_block_editor_for_post', function ( $use, $post ) {
	return ip_is_slug_template_page( $post ) ? false : $use;
}, 20, 2 );

add_action( 'load-post.php', function () {
	$id = isset( $_GET['post'] ) ? absint( $_GET['post'] ) : 0; // phpcs:ignore WordPress.Security.NonceVerification -- read-only screen check.
	if ( ! $id || ! ip_is_slug_template_page( $id ) ) {
		return;
	}
	remove_post_type_support( 'page', 'editor' ); // This request only.
	add_action( 'edit_form_after_title', function () {
		echo '<div class="notice notice-info inline"><p>' . esc_html__( 'Diese Seite wird vom Theme gestaltet. Die Inhalte pflegen Sie in den Feldern unten; der frühere Seiteninhalt (Elementor) wird nicht mehr angezeigt.', 'infoplus' ) . '</p></div>';
	} );
} );

/*
 * Never-saved repeater, gallery and relationship fields of the theme's page
 * groups get their default_value on the edit screen too. SCF applies a
 * field's default_value itself only for simple fields; a repeater's type
 * filter turns the default rows into false (it expects a row count), so the
 * client would see an empty list and the first save would erase the old
 * content. Runs after the type filters (priority 10) and only when the meta
 * row does not exist at all: a list the client emptied stays empty.
 * The front end does not need this (ip_field() reads the defaults), except
 * for a field added to a group after the page was first saved; this covers
 * that case as well.
 */
add_filter( 'acf/load_value', function ( $value, $post_id, $field ) {
	if ( ! empty( $value ) || ! is_numeric( $post_id ) || empty( $field['key'] ) || empty( $field['default_value'] ) || ! is_array( $field['default_value'] ) ) {
		return $value;
	}
	if ( ! str_starts_with( $field['key'], 'field_ip_' ) || str_starts_with( $field['key'], 'field_ip_opt_' ) ) {
		return $value;
	}
	if ( empty( $field['parent'] ) || ! str_starts_with( (string) $field['parent'], 'group_ip_' ) ) {
		return $value; // Top-level fields only; sub-field names carry row indexes.
	}
	if ( metadata_exists( 'post', (int) $post_id, $field['name'] ) ) {
		return $value;
	}
	if ( 'repeater' !== $field['type'] ) {
		return $field['default_value']; // gallery, relationship: plain ID lists.
	}
	// Repeater rows in the shape the field renders: keyed by sub-field key.
	$keys = array();
	foreach ( (array) ( $field['sub_fields'] ?? array() ) as $sub ) {
		$keys[ $sub['name'] ] = $sub['key'];
	}
	$rows = array();
	foreach ( $field['default_value'] as $row ) {
		$keyed = array();
		foreach ( (array) $row as $name => $sub_value ) {
			if ( isset( $keys[ $name ] ) ) {
				$keyed[ $keys[ $name ] ] = $sub_value;
			}
		}
		$rows[] = $keyed;
	}
	return $rows;
}, 20, 3 );

/* ── Assets ─────────────────────────────────────────────────────────────── */

add_action( 'wp_enqueue_scripts', function () {
	// The product cards on the front page are styled in the listing bundle.
	if ( is_front_page() && function_exists( 'ip_enqueue' ) ) {
		ip_enqueue( 'ip-archive', 'assets/css/archive.css', array( 'ip-main' ) );
	}
}, 20 );

/* ── Plain pages: content without Elementor ─────────────────────────────── */

/** Decoded _elementor_data of a page built with Elementor, or null. */
function ip_elementor_data( $post_id ) {
	if ( 'builder' !== get_post_meta( $post_id, '_elementor_edit_mode', true ) ) {
		return null;
	}
	$raw  = get_post_meta( $post_id, '_elementor_data', true );
	$data = is_string( $raw ) ? json_decode( $raw, true ) : $raw;
	return is_array( $data ) && $data ? $data : null;
}

/** First widget of an Elementor tree in document order, or null. */
function ip_elementor_first_widget( $elements ) {
	foreach ( (array) $elements as $el ) {
		if ( 'widget' === ( $el['elType'] ?? '' ) ) {
			return $el;
		}
		$found = ip_elementor_first_widget( $el['elements'] ?? array() );
		if ( $found ) {
			return $found;
		}
	}
	return null;
}

/**
 * Title and body of a plain page, cached per request:
 * array( 'title' => string, 'html' => string|null ). 'html' is null when
 * the page is not an Elementor document (then page.php uses the_content()).
 *
 * The old Elementor pages hide the WordPress title and open with a heading
 * widget instead ("Allgemeine Geschäftsbedingungen (AGB) - Stand: April 2019"
 * on the page titled "AGB"). That first heading becomes the page's H1 and is
 * not repeated in the body.
 */
function ip_page_parts( $post = null ) {
	static $cache = array();
	$post = get_post( $post );
	if ( ! $post ) {
		return array( 'title' => '', 'html' => null );
	}
	if ( isset( $cache[ $post->ID ] ) ) {
		return $cache[ $post->ID ];
	}
	$parts = array( 'title' => get_the_title( $post ), 'html' => null );
	$data  = ip_elementor_data( $post->ID );
	if ( $data ) {
		$ctx   = array( 'skip' => '' );
		$first = ip_elementor_first_widget( $data );
		if ( $first && 'heading' === ( $first['widgetType'] ?? '' ) && '' !== trim( wp_strip_all_tags( (string) ( $first['settings']['title'] ?? '' ) ) ) ) {
			$parts['title'] = trim( preg_replace( '/\s+/u', ' ', wp_strip_all_tags( str_ireplace( array( '<br>', '<br/>', '<br />' ), ' ', $first['settings']['title'] ) ) ) );
			$ctx['skip']    = $first['id'];
		}
		$html = ip_elementor_html( $data, $ctx );
		if ( '' === trim( wp_strip_all_tags( $html ) ) && false === stripos( $html, '<img' ) ) {
			// Nothing convertible (e.g. only an HTML widget): use the plain HTML
			// copy Elementor keeps in post_content, without its filters.
			$html = ip_rich( $post->post_content );
		}
		$parts['html'] = $html;
	}
	return $cache[ $post->ID ] = $parts;
}

/** H1 text of a plain page (see ip_page_parts()). */
function ip_page_title( $post = null ) {
	return ip_page_parts( $post )['title'];
}

/**
 * Body of a plain page. Prints.
 *
 * A page built with Elementor (_elementor_edit_mode = builder) cannot go
 * through the_content() while Elementor is active: its the_content filter
 * replaces the text with Elementor's own builder markup. Such a page is
 * rendered from its _elementor_data instead (ip_elementor_html()), read
 * only, so nothing in the database changes and the page keeps working after
 * Elementor is switched off. Every other page uses the_content().
 *
 * Long-term fix (needs the owner's approval, it writes to the database):
 * copy this converted HTML into post_content once and drop
 * _elementor_edit_mode, so the pages become normal editor pages.
 */
function ip_page_content( $post = null ) {
	$parts = ip_page_parts( $post );
	if ( null === $parts['html'] ) {
		the_content();
		return;
	}
	echo $parts['html']; // phpcs:ignore WordPress.Security.EscapeOutput -- built from escaped parts in ip_elementor_html().
}

/** Attributes for a link from an Elementor link setting (url, is_external, nofollow). Returns '' or ' href="…"…'. */
function ip_elementor_link_attrs( $link ) {
	$url = is_array( $link ) ? trim( (string) ( $link['url'] ?? '' ) ) : '';
	if ( '' === $url ) {
		return '';
	}
	$attrs = ' href="' . esc_url( $url ) . '"';
	$rel   = array();
	if ( ! empty( $link['is_external'] ) ) {
		$attrs .= ' target="_blank"';
		$rel[]  = 'noopener';
	}
	if ( ! empty( $link['nofollow'] ) ) {
		$rel[] = 'nofollow';
	}
	return $rel ? $attrs . ' rel="' . esc_attr( implode( ' ', $rel ) ) . '"' : $attrs;
}

/**
 * Clean HTML from an Elementor element tree. Returns safe HTML.
 *
 * Handled: heading (h2 to h6 by its header_size; h1 becomes h2 because the
 * page has its own H1), text-editor (its editor HTML through ip_rich()),
 * image (wp_get_attachment_image via ip_img(), optional link and caption),
 * button (a link styled as a button), icon-list (ul), nested-accordion
 * (details/summary), nested-tabs (a heading per tab), divider (hr).
 * Layout-only elements (section, column, container, inner-section) are
 * walked through without markup. Everything else (spacer, html, shortcode,
 * forms, loops, third-party widgets) is skipped on purpose: it is either
 * layout, or code that must not run outside Elementor.
 * Dynamic tags (__dynamic__) are not resolved; the static value is used.
 *
 * @param array $elements Elements (decoded _elementor_data or children).
 * @param array $ctx      'skip' => element ID left out (the heading used as H1).
 */
function ip_elementor_html( $elements, &$ctx ) {
	$out = '';
	foreach ( (array) $elements as $el ) {
		if ( ! is_array( $el ) ) {
			continue;
		}
		$children = $el['elements'] ?? array();
		if ( 'widget' !== ( $el['elType'] ?? '' ) ) {
			$out .= ip_elementor_html( $children, $ctx );
			continue;
		}
		if ( ! empty( $ctx['skip'] ) && ( $el['id'] ?? '' ) === $ctx['skip'] ) {
			continue;
		}
		$s = (array) ( $el['settings'] ?? array() );
		switch ( $el['widgetType'] ?? '' ) {
			case 'heading':
				$title = trim( (string) ( $s['title'] ?? '' ) );
				if ( '' === $title ) {
					break;
				}
				$tag   = in_array( $s['header_size'] ?? '', array( 'h2', 'h3', 'h4', 'h5', 'h6' ), true ) ? $s['header_size'] : 'h2';
				$inner = nl2br( wp_kses( $title, array( 'br' => array(), 'strong' => array(), 'b' => array(), 'em' => array(), 'i' => array() ) ), false );
				$link  = ip_elementor_link_attrs( $s['link'] ?? null );
				$out  .= sprintf( '<%1$s>%2$s</%1$s>', $tag, $link ? '<a' . $link . '>' . $inner . '</a>' : $inner );
				break;

			case 'text-editor':
				$out .= ip_rich( $s['editor'] ?? '' );
				break;

			case 'image':
				$id = (int) ( $s['image']['id'] ?? 0 );
				if ( ! $id ) {
					break;
				}
				$link = '';
				if ( 'custom' === ( $s['link_to'] ?? '' ) ) {
					$link = ip_elementor_link_attrs( $s['link'] ?? null );
				} elseif ( 'file' === ( $s['link_to'] ?? '' ) ) {
					$link = ' href="' . esc_url( (string) wp_get_attachment_url( $id ) ) . '"';
				}
				$attr = array();
				if ( $link && '' === trim( (string) get_post_meta( $id, '_wp_attachment_image_alt', true ) ) ) {
					// A linked image is the link's only content: it needs a name (the
					// Alture logo on the Impressum has no alt text in the library).
					$attr['alt'] = trim( preg_replace( '/[_-]+/', ' ', get_the_title( $id ) ) );
				}
				$image = ip_img( $id, '(min-width: 800px) 720px, 100vw', $attr, 'ip-1200' );
				if ( ! $image ) {
					break;
				}
				$caption = 'custom' === ( $s['caption_source'] ?? '' ) ? (string) ( $s['caption'] ?? '' ) : ( 'attachment' === ( $s['caption_source'] ?? '' ) ? wp_get_attachment_caption( $id ) : '' );
				$out    .= '<figure class="ip-prose__figure">' . ( $link ? '<a' . $link . '>' . $image . '</a>' : $image )
					. ( $caption ? '<figcaption>' . esc_html( $caption ) . '</figcaption>' : '' ) . '</figure>';
				break;

			case 'button':
				$text = trim( (string) ( $s['text'] ?? '' ) );
				$link = ip_elementor_link_attrs( $s['link'] ?? null );
				if ( '' !== $text && $link ) {
					$out .= '<p class="ip-prose__action"><a class="ip-btn"' . $link . '>' . esc_html( $text ) . '</a></p>';
				}
				break;

			case 'icon-list':
				$items = '';
				foreach ( (array) ( $s['icon_list'] ?? array() ) as $item ) {
					$text = trim( (string) ( $item['text'] ?? '' ) );
					if ( '' === $text ) {
						continue;
					}
					$text  = wp_kses( $text, array( 'br' => array(), 'strong' => array(), 'b' => array(), 'em' => array() ) );
					$link  = ip_elementor_link_attrs( $item['link'] ?? null );
					$items .= '<li>' . ( $link ? '<a' . $link . '>' . $text . '</a>' : $text ) . '</li>';
				}
				$out .= $items ? '<ul>' . $items . '</ul>' : '';
				break;

			case 'nested-accordion':
				foreach ( (array) ( $s['items'] ?? array() ) as $i => $item ) {
					$title = trim( (string) ( $item['item_title'] ?? '' ) );
					$body  = ip_elementor_html( isset( $children[ $i ] ) ? array( $children[ $i ] ) : array(), $ctx );
					if ( '' !== $title ) {
						$out .= '<details class="ip-prose__details"><summary>' . esc_html( $title ) . '</summary>' . $body . '</details>';
					}
				}
				break;

			case 'nested-tabs':
				foreach ( (array) ( $s['tabs'] ?? array() ) as $i => $tab ) {
					$title = trim( (string) ( $tab['tab_title'] ?? '' ) );
					$out  .= ( '' !== $title ? '<h2>' . esc_html( $title ) . '</h2>' : '' )
						. ip_elementor_html( isset( $children[ $i ] ) ? array( $children[ $i ] ) : array(), $ctx );
				}
				break;

			case 'divider':
				$out .= '<hr>';
				break;

			default:
				// spacer, html, shortcode, form, loop-grid and third-party widgets: skipped (see docblock).
				break;
		}
	}
	return $out;
}

/* ── News ───────────────────────────────────────────────────────────────── */

add_filter( 'ip_setting_defaults', function ( $defaults ) {
	return array_merge( $defaults, array(
		// Old single news template 13266: "Related News" (English in the old build).
		'news_related_title' => 'Weitere News',
		'news_back_label'    => 'Zurück zum Dashboard', // Old: "Back to dashboard" -> /account/.
	) );
} );

/**
 * IDs of the latest other published news, for "Weitere News".
 *
 * @return int[]
 */
function ip_news_related( $post_id, $count = 3 ) {
	return get_posts( array(
		'post_type'              => 'news',
		'post_status'            => 'publish',
		'posts_per_page'         => $count,
		'post__not_in'           => array( (int) $post_id ),
		'fields'                 => 'ids',
		'no_found_rows'          => true,
		'ignore_sticky_posts'    => true,
		'update_post_term_cache' => false,
	) );
}
